// fetch all customers
const r = await api.get('/customers', {});
// assume response data is array of customers
const customers = r.data || [];
let count = 0;
for (const c of customers) {
  if (c.birthday) {
    const month = new Date(c.birthday).getMonth() + 1; // getMonth 0-indexed
    if (month === 11) count++;
  }
}
return {count, total: customers.length};

const r = await api.get('/customers', { limit: 1000 });
const customers = r.data || [];
let count = 0;
for (const c of customers) {
  if (c.birthday) {
    const month = new Date(c.birthday).getMonth() + 1;
    if (month === 11) count++;
  }
}
return {count, total: customers.length};

